 sudeva: { av: "🧭", en: "Sudeva", te: "సుదేవుడు", d: "A brahmin sent by Damayantī's father to search for her, and later sent by her to Ayodhyā.", dt: "దమయంతిని వెతకడానికి ఆమె తండ్రి పంపిన బ్రాహ్మణుడు; తరువాత ఆమె అతన్ని అయోధ్యకు పంపింది." },
 keshini: { av: "👧", en: "Keśinī", te: "కేశిని", d: "Damayantī's clever maid, who watched the charioteer Bāhuka and reported his wonders.", dt: "దమయంతి తెలివైన చెలికత్తె; బాహుకుని గమనించి అతని అద్భుతాలను చెప్పింది." },
 agastya_m: { av: "🌊", en: "Agastya", te: "అగస్త్య మహర్షి", d: "The short, mighty sage who digested the demon Vātāpi, drank up the ocean, and made the Vindhya mountains bow.", dt: "వాతాపిని జీర్ణించుకున్న, సముద్రాన్ని తాగిన, వింధ్యపర్వతాన్ని వంచిన పొట్టి, మహాశక్తిమంతుడైన మహర్షి." },
 lopamudra: { av: "🌺", en: "Lopāmudrā", te: "లోపాముద్ర", d: "Agastya's wise wife, created by him from the finest parts of every creature and raised as a princess of Vidarbha.", dt: "అగస్త్యుని జ్ఞానవతియైన భార్య; అన్ని ప్రాణుల శ్రేష్ఠమైన అంశాలతో ఆయనే సృష్టించగా విదర్భ రాకుమారిగా పెరిగింది." },
