 mudgala: { av: "🌾", en: "Mudgala", te: "ముద్గలుడు", d: "A poor sage who lived on gleaned grain and gave half of it away, and who turned down heaven itself.", dt: "పొలాల్లో రాలిన గింజలు ఏరుకుని జీవిస్తూ, అందులో సగం దానం చేసిన పేద మహర్షి; స్వర్గాన్నే కాదన్నాడు." },
 rama: { av: "🏹", en: "Rāma", te: "శ్రీరాముడు", d: "Prince of Ayodhyā and avatar of Viṣṇu, whose story Mārkaṇḍeya told the Pāṇḍavas.", dt: "అయోధ్య రాకుమారుడు, విష్ణువు అవతారం; ఆయన కథను మార్కండేయుడు పాండవులకు చెప్పాడు." },
 sita: { av: "🌷", en: "Sītā", te: "సీత", d: "Rāma's wife, carried off by Rāvaṇa and won back after a great war.", dt: "శ్రీరాముని భార్య; రావణుడు అపహరించగా మహాయుద్ధం తరువాత తిరిగి పొందబడింది." },
 ravana: { av: "👑", en: "Rāvaṇa", te: "రావణుడు", d: "The ten-headed king of Laṅkā who carried off Sītā.", dt: "సీతను అపహరించిన పది తలల లంకాధిపతి." },
 savitri: { av: "🌅", en: "Sāvitrī", te: "సావిత్రి", d: "Princess of Madra who chose Satyavān knowing he would die in a year, and won his life back from Yama himself.", dt: "ఏడాదిలో చనిపోతాడని తెలిసీ సత్యవంతుని వరించి, యముడి నుండే అతని ప్రాణాన్ని తిరిగి గెలుచుకున్న మద్రదేశ రాకుమారి." },
